    "some wine, a glass of": "немного вина, бокал",
    "{Leib} is the dark rye bread Estonians eat every day. White bread is {sai}, from lesson 24.": "{Leib} это тёмный ржаной хлеб, который эстонцы едят каждый день. Белый хлеб это {sai}, из урока 24.",
    "{Toit} is food in general, the word on a menu or a shop sign.": "{Toit} это еда вообще, слово из меню или с вывески магазина.",
    "Say what you eat.": "Скажите, что вы едите.",
    "Say you'd like bread and cheese.": "Скажите, что вам хотелось бы хлеба и сыра.",
    "I'd like bread and cheese.": "Мне хотелось бы хлеба и сыра.",
    "Offer somebody soup.": "Предложите кому-нибудь суп.",
    "Do you want some soup?": "Хочешь супа?",
    "Excuse me, how much is this?": "Извините, сколько это стоит?",
    "Three euros.": "Три евро.",
    "And the cake?": "А торт?",
    "The cake is four euros fifty.": "Торт стоит четыре евро пятьдесят.",
    "Fine. One cake and one coffee, please.": "Хорошо. Один торт и один кофе, пожалуйста.",
    "Seven fifty altogether. By card?": "Всего семь пятьдесят. Картой?",
    "Yes, by card.": "Да, картой.",
    "How much does it cost?": "Сколько это стоит?",
    "to cost, to pay": "стоить, платить",
    "euro": "евро",
    "euros, after a number": "евро, после числа",
    "cent": "цент",
