    "a door": "дверь",
    "Say it's here.": "Скажите, что это здесь.",
    "Where's the kitchen?": "Где кухня?",
    "The kitchen's here.": "Кухня здесь.",
    "It's a table. Say so.": "Это стол. Скажите это.",
    "It's a table.": "Это стол.",
