    "I'm still at work.": "Я ещё на работе.",
    "And where are you going after that?": "А куда ты пойдёшь потом?",
    "From work I'm going to the shop, and then home.": "С работы я иду в магазин, а потом домой.",
    "I'm coming to the shop too! See you in the shop, then!": "Я тоже иду в магазин! Тогда увидимся в магазине!",
    "where to": "куда",
    "where from": "откуда",
