    "Weather is {on} and how it is, {Täna on külm}, or {sajab} and what's falling: {Sajab vihma}.": "О погоде говорят {on} и какая она, {Täna on külm}, или {sajab} и что падает: {Sajab vihma}.",
    "There's no it in {On külm}. Estonian says just \"is cold\", and that's a whole sentence.": "В {On külm} нет слова «оно». По-эстонски говорят просто «есть холодно», и это целое предложение.",
    "{Sajab vihma} is word for word \"falls rain\", and the rain is in the {osastav}, as after {tahan}.": "{Sajab vihma} дословно значит «падает дождь», и дождь стоит в {osastav}, как после {tahan}.",
    "{Väljas} is outside: {Väljas on külm}.": "{Väljas} значит «на улице»: {Väljas on külm}.",
    "Estonians often open a chat with a neighbor on the weather.": "Эстонцы часто начинают разговор с соседом с погоды.",
    "Estonians often open a chat with a neighbor on the weather, so this is one of the most useful lessons of the part.": "Эстонцы часто начинают разговор с соседом с погоды, так что это один из самых полезных уроков этой части.",
