    "Very good. By card, please.": "Очень хорошо. Картой, пожалуйста.",
    "A whole visit to a shop, made only of what this part and the ones before it taught.": "Целый поход в магазин, только из того, чему научили эта часть и предыдущие.",
    "What you need, and a color, is enough to be shown it.": "Того, что вам нужно, и цвета хватит, чтобы вам её показали.",
    "Tom opens with the weather and the shop assistant picks it up. That's how a lot of small talk in Estonia starts.": "Том начинает с погоды, и продавец подхватывает. Так в Эстонии начинаются многие короткие разговоры.",
