    "And in the evening?": "А вечером?",
    "In the evening I went to the shop. And you?": "Вечером я сходил в магазин. А ты?",
    "I was at work. In the evening I ate and had some tea.": "Я был на работе. Вечером поел и выпил чаю.",
    "What did you do yesterday?": "Что ты делал вчера?",
    "to go and come back, to visit": "сходить и вернуться, побывать",
    "I go (and come back)": "я хожу (и возвращаюсь)",
    "I was": "я был",
    "I did, I made": "я делал, я сделал",
    "I read (yesterday)": "я читал (вчера)",
    "I went, I visited": "я ходил, я побывал",
    "I ate": "я ел",
    "I drank": "я пил",
    "The past for I ends in -in, and the rest of the word is learned with each verb: {olin}, {tegin}, {sõin}.": "Прошедшее время для «я» кончается на -in, а остальная часть слова заучивается с каждым глаголом: {olin}, {tegin}, {sõin}.",
    "With {käisin}, the place is where you were, not where to: {Ma käisin poes}, never with {poodi}.": "С {käisin} называют место, где вы были, а не куда: {Ma käisin poes}, никогда не с {poodi}.",
    "{Käisin} is the usual way to say you went somewhere and came back: {Ma käisin poes}, I went to the shop.": "{Käisin} это обычный способ сказать, что вы куда-то сходили и вернулись: {Ma käisin poes}, я сходил в магазин.",
    "{Mida sa eile tegid?} is what did you do yesterday. Take it whole for now; the other persons are the next lesson.": "{Mida sa eile tegid?} значит «что ты делал вчера?». Пока запомните это целиком; остальные лица будут в следующем уроке.",
    "Now": "Сейчас",
    "Say you were at home and read a book.": "Скажите, что вы были дома и читали книгу.",
    "I was at home and read a book.": "Я был дома и читал книгу.",
