    "in a café": "в кафе",
    "The past has six forms, -in, -id, -s or -i, -ime, -ite, -id. For {ta} some verbs end in -s and some in -i: {käis}, but {oli} and {tegi}.": "У прошедшего времени шесть форм: -in, -id, -s или -i, -ime, -ite, -id. В форме {ta} одни глаголы оканчиваются на -s, а другие на -i: {käis}, но {oli} и {tegi}.",
    "{Sa olid} and {nad olid} are the same word, and so are {sa tegid} and {nad tegid}. The person in front tells you which.": "{Sa olid} и {nad olid} это одно и то же слово, как и {sa tegid} и {nad tegid}. Кто именно, подсказывает местоимение впереди.",
    "Say you were in Tartu.": "Скажите, что вы были в Тарту.",
    "Where were you on Saturday?": "Где ты был в субботу?",
