    "Ask a friend what they did on Sunday.": "Спросите друга, что он делал в воскресенье.",
    "What did you do on Sunday?": "Что ты делал в воскресенье?",
    "Say you went to a café.": "Скажите, что вы ходили в кафе.",
    "We went to a café.": "Мы ходили в кафе.",
    "Tom, I ask and you answer.": "Том, я спрашиваю, а ты отвечаешь.",
    "All right.": "Хорошо.",
