    "Say which languages you speak.": "Скажіть, якими мовами ви розмовляєте.",
    "I speak English and a little Estonian.": "Я розмовляю англійською і трохи естонською.",
    "Tom, do you live in Tallinn?": "Томе, ти живеш у Таллінні?",
    "No, I don't live in Tallinn. I live in Tartu.": "Ні, я не живу в Таллінні. Я живу в Тарту.",
