    "of course": "звісно",
    "You've been doing this since lesson 6, where {olen} became {ei ole}.": "Ви робите це з уроку 6, де {olen} стало {ei ole}.",
    "Say no, you don't live in Tallinn. You live in Tartu.": "Скажіть, що ні, ви не живете в Таллінні. Ви живете в Тарту.",
    "Do you live in Tallinn?": "Ти живеш у Таллінні?",
    "Say no, you don't.": "Скажіть, що ні.",
    "Say you don't speak Estonian well yet.": "Скажіть, що ви ще не дуже добре розмовляєте естонською.",
    "I don't speak Estonian well yet.": "Я ще не дуже добре розмовляю естонською.",
    "Say yes, of course.": "Скажіть «так, звісно».",
    "Are you learning Estonian?": "Ти вчиш естонську?",
    "Tom, what's your phone number?": "Томе, який у тебе номер телефону?",
    "Five, two, zero, one, three, seven, eight.": "П'ять, два, нуль, один, три, сім, вісім.",
    "Slower, please!": "Повільніше, будь ласка!",
    "Five. Two. Zero. One. Three. Seven. Eight.": "П'ять. Два. Нуль. Один. Три. Сім. Вісім.",
    "Thanks! Mine is five, four, nine, six, zero, one, two.": "Дякую! Мій: п'ять, чотири, дев'ять, шість, нуль, один, два.",
