    "number": "номер",
    "phone number": "номер телефону",
    "Ten words, and a phone number is said one digit at a time.": "Десять слів, а номер телефону називають по одній цифрі.",
    "{Kuus}, six, has a long uu. Hold it, or it turns into another word.": "{Kuus}, шість, має довге uu. Тягніть його, інакше вийде інше слово.",
    "{Telefoninumber} is {telefon} and {number} written as one word. Estonian builds long words by putting short ones together, and you'll see it everywhere.": "{Telefoninumber} це {telefon} і {number}, написані одним словом. Естонська будує довгі слова, з'єднуючи короткі, і ви побачите це всюди.",
    "{Kaheksa} and {üheksa} are eight and nine, and they sound alike. Listen to the first sound.": "{Kaheksa} і {üheksa}: вісім і дев'ять, і звучать вони схоже. Слухайте перший звук.",
    "{Mis su telefoninumber on?} is built just like {Mis su nimi on?}": "{Mis su telefoninumber on?} будується так само, як {Mis su nimi on?}",
    "Number": "Число",
    "Say a phone number, one digit at a time. Any one will do.": "Назвіть номер телефону по одній цифрі. Підійде будь-який.",
    "What's your phone number?": "Який у тебе номер телефону?",
