    "restaurant": "ресторан",
    "car": "машина, автомобіль",
    "taxi": "таксі",
    "on foot": "пішки",
    "at school": "у школі",
    "at the university": "в університеті",
    "in the town center": "у центрі міста",
    "at a hotel": "у готелі",
    "at a restaurant": "у ресторані",
    "by car": "машиною",
    "by taxi": "таксі",
    "Walking is {jalgsi}, a word of its own. There is no vehicle, so there is no -ga.": "Пішки буде {jalgsi}, окреме слово. Транспорту немає, тому немає і -ga.",
    "{Ülikool} is a big {kool}, and the ending goes on it the same way: {ülikoolis}.": "{Ülikool} це велика школа, {kool}, і закінчення додається до нього так само: {ülikoolis}.",
    "With its ending": "Із закінченням",
    "Say you work at a school, or anywhere you like.": "Скажіть, що працюєте в школі або будь-де.",
    "I work at a school.": "Я працюю в школі.",
    "Say by car.": "Скажіть «машиною».",
    "By car.": "Машиною.",
    "Say you walk.": "Скажіть, що ходите пішки.",
    "I walk.": "Я ходжу пішки.",
    "Ask where the hotel is.": "Запитайте, де готель.",
    "Where's the hotel?": "Де готель?",
    "Excuse me, where's the bus station?": "Перепрошую, де автовокзал?",
    "The bus station? Straight on and then right.": "Автовокзал? Прямо, а потім праворуч.",
    "No, it's close. Where are you going?": "Ні, близько. Куди ви їдете?",
    "I'm going to Tartu.": "Я їду до Тарту.",
    "To Tartu? By bus or by train?": "До Тарту? Автобусом чи поїздом?",
    "By bus. Thank you! Goodbye!": "Автобусом. Дякую! До побачення!",
    "A whole conversation with a stranger, made only of what this part taught.": "Ціла розмова з незнайомою людиною, лише з того, чого навчила ця частина.",
    "You don't have to understand every word of the directions. Catch {otse}, {vasakule} and {paremale}, and the rest is pointing.": "Не обов'язково розуміти кожне слово, коли вам пояснюють дорогу. Вловіть {otse}, {vasakule} і {paremale}, а решту покажуть рукою.",
    "Notice how Tom asks: {Vabandust} first, then the question.": "Зверніть увагу, як питає Том: спочатку {Vabandust}, потім питання.",
    "Liis asks {Kuhu te sõidate?} with {teie}, the polite you, because Tom is a stranger. He answers with {ma} as ever.": "Лійс питає {Kuhu te sõidate?} з {teie}, ввічливим «ви», бо Том для неї незнайомець. Він, як завжди, відповідає з {ma}.",
    "Notice how Tom asks: {Vabandust} first, then the question. That's all the politeness it needs.": "Зверніть увагу, як питає Том: спочатку {Vabandust}, потім питання. Більше ввічливості й не треба.",
    "Stop a stranger and ask where the bus station is.": "Зупиніть незнайому людину й запитайте, де автовокзал.",
    "Say you're going to Tartu.": "Скажіть, що їдете до Тарту.",
    "Say no, by train.": "Скажіть: ні, поїздом.",
    "By bus?": "Автобусом?",
    "No, by train.": "Ні, поїздом.",
    "Yes?": "Так?",
    "Ask whether it's far.": "Запитайте, чи це далеко.",
    "You're in town and need the pharmacy. Stop somebody and ask. They answer first in Estonian.": "Ви в місті, і вам потрібна аптека. Зупиніть когось і запитайте. Спочатку вам відповідають естонською.",
    "No, it's small. But it's nice.": "Ні, маленька. Але гарна.",
    "And the kitchen?": "А кухня?",
    "The kitchen's really small! But the window's big.": "Кухня зовсім маленька! Зате вікно велике.",
    "And the building? Is it new?": "А будинок? Він новий?",
    "No, the building's old. But it's good!": "Ні, будинок старий. Але хороший!",
    "big": "великий",
    "small": "маленький",
    "new": "новий",
    "beautiful, nice": "гарний, приємний",
    "expensive, dear": "дорогий, любий",
    "cheap": "дешевий",
    "Most of these come in pairs, so learn them as pairs and say them aloud together: {suur, väike}.": "Більшість із них ідуть парами, тож вивчайте їх парами й вимовляйте вголос разом: {suur, väike}.",
    "And its opposite": "І його протилежність",
    "Say no, it's small, but nice.": "Скажіть: ні, маленька, але гарна.",
    "No, it's small, but nice.": "Ні, маленька, але гарна.",
    "Say the coffee here is expensive.": "Скажіть, що кава тут дорога.",
    "The coffee here is expensive.": "Кава тут дорога.",
    "Say no, it's old.": "Скажіть: ні, він старий.",
    "No, it's old.": "Ні, він старий.",
    "Tom, how's your new job?": "Томе, як твоя нова робота?",
    "Interesting, but hard.": "Цікава, але важка.",
    "And Estonian? Is it hard?": "А естонська? Вона важка?",
    "A little hard, but beautiful.": "Трохи важка, але гарна.",
    "Is the lesson long?": "Урок довгий?",
    "No, short. But the teacher is very fast!": "Ні, короткий. Але вчитель дуже швидкий!",
    "And you're slow?": "А ти повільний?",
    "Yes, a little!": "Так, трохи!",
    "long, tall": "довгий, високий",
    "short": "короткий",
    "fast, in a hurry": "швидкий, у поспіху",
    "slow": "повільний",
    "hard, difficult; heavy": "важкий, складний; тяжкий",
    "light; easy": "легкий (на вагу); нескладний",
    "interesting": "цікавий",
    "boring": "нудний",
    "young": "молодий",
    "lesson; hour": "урок; година",
    "Describing words come in pairs, so learn them as opposites, as in lesson 36: {pikk} and {lühike}.": "Описові слова йдуть парами, тож вивчайте їх як протилежності, як в уроці 36: {pikk} і {lühike}.",
    "The opposite": "Протилежність",
    "Say it's a little hard, but beautiful.": "Скажіть, що вона трохи важка, але гарна.",
    "Is Estonian hard?": "Естонська важка?",
    "Say it's interesting.": "Скажіть, що вона цікава.",
    "How's your job?": "Як твоя робота?",
    "Interesting!": "Цікава!",
    "Say you're in a hurry.": "Скажіть, що ви поспішаєте.",
    "I'm in a hurry.": "Я поспішаю.",
    "Tom, what color is your phone?": "Томе, якого кольору твій телефон?",
    "Black. And yours?": "Чорного. А твій?",
    "My phone's red. I love red!": "Мій телефон червоний. Я люблю червоний!",
    "I like blue. And green.": "Мені подобається синій. І зелений.",
    "And what color is your kitchen?": "А якого кольору твоя кухня?",
    "White and yellow.": "Біла й жовта.",
    "What color?": "Якого кольору?",
    "color": "колір",
    "yellow": "жовтий",
    "Ask {Mis värvi?} and answer with the color, as it is: {Must}.": "Запитайте {Mis värvi?} і відповідайте назвою кольору без змін: {Must}.",
    "Four of the colors end the same way: {punane}, {sinine}, {roheline}, {kollane}. Say them aloud as a list.": "Чотири кольори закінчуються однаково: {punane}, {sinine}, {roheline}, {kollane}. Вимовте їх уголос списком.",
