    "Weather is {on} and how it is, {Täna on külm}, or {sajab} and what's falling: {Sajab vihma}.": "Про погоду кажуть {on} і яка вона, {Täna on külm}, або {sajab} і що падає: {Sajab vihma}.",
    "There's no it in {On külm}. Estonian says just \"is cold\", and that's a whole sentence.": "У {On külm} немає слова «воно». Естонською кажуть просто «є холодно», і це ціле речення.",
    "{Sajab vihma} is word for word \"falls rain\", and the rain is in the {osastav}, as after {tahan}.": "{Sajab vihma} дослівно означає «падає дощ», і дощ стоїть в {osastav}, як після {tahan}.",
    "{Väljas} is outside: {Väljas on külm}.": "{Väljas} означає «надворі»: {Väljas on külm}.",
    "Estonians often open a chat with a neighbor on the weather.": "Естонці часто починають розмову із сусідом з погоди.",
