    "It's wet outside.": "Надворі мокро.",
    "Hello! I need a hat. It's really cold today!": "Добрий день! Мені потрібна шапка. Сьогодні дуже холодно!",
    "Yes, it's cold outside. What color?": "Так, надворі холодно. Якого кольору?",
    "Gray or black.": "Сіра або чорна.",
    "This gray hat is good. And cheap!": "Ця сіра шапка гарна. І дешева!",
    "Ten euros.": "Десять євро.",
    "Very good. By card, please.": "Дуже добре. Карткою, будь ласка.",
    "A whole visit to a shop, made only of what this part and the ones before it taught.": "Цілий похід до магазину, лише з того, чого навчили ця частина й попередні.",
    "What you need, and a color, is enough to be shown it.": "Того, що вам потрібно, і кольору досить, щоб вам її показали.",
    "Tom opens with the weather and the shop assistant picks it up. That's how a lot of small talk in Estonia starts.": "Том починає з погоди, і продавець підхоплює. Так в Естонії починається чимало коротких розмов.",
