    "Say gray or black.": "Скажіть: сіра або чорна.",
    "Yes, it's cold outside! What color?": "Так, надворі холодно! Якого кольору?",
    "This gray hat is nice.": "Ця сіра шапка гарна.",
    "Say very good, by card.": "Скажіть: дуже добре, карткою.",
    "It's a cold day and you need a hat. The shop assistant speaks first.": "Холодний день, і вам потрібна шапка. Продавець говорить першим.",
    "Tom, what are you doing tomorrow?": "Томе, що ти робиш завтра?",
    "Tomorrow I'm working. And on Saturday I'm going to Tartu.": "Завтра я працюю. А в суботу їду до Тарту.",
    "And next week?": "А наступного тижня?",
    "I don't know. Maybe I'll be at home.": "Не знаю. Може, буду вдома.",
    "I'm in Tallinn next week! Shall we meet up?": "Я наступного тижня в Таллінні! Зустрінемося?",
    "Yes, definitely!": "Так, обов'язково!",
    "next": "наступний",
    "next week": "наступного тижня",
    "maybe": "можливо",
    "definitely, for sure": "обов'язково, точно",
    "Let's meet up!": "Давай зустрінемося!",
    "Estonian has no future tense. The present and a word for when says it: {Homme ma töötan}, I'll work tomorrow.": "В естонській немає майбутнього часу. Його передають теперішній час і слово, що каже коли: {Homme ma töötan}, завтра я працюватиму.",
    "The word for when often goes first, and the rest follows as in any sentence: {Homme ma töötan}.": "Слово, що каже коли, часто стоїть першим, а решта йде, як у будь-якому реченні: {Homme ma töötan}.",
    "Say you're working tomorrow.": "Скажіть, що завтра ви працюєте.",
