    "I ate": "я їв",
    "I drank": "я пив",
    "The past for I ends in -in, and the rest of the word is learned with each verb: {olin}, {tegin}, {sõin}.": "Минулий час для «я» закінчується на -in, а решту слова вивчають із кожним дієсловом: {olin}, {tegin}, {sõin}.",
    "With {käisin}, the place is where you were, not where to: {Ma käisin poes}, never with {poodi}.": "З {käisin} називають місце, де ви були, а не куди: {Ma käisin poes}, ніколи не з {poodi}.",
    "{Käisin} is the usual way to say you went somewhere and came back: {Ma käisin poes}, I went to the shop.": "{Käisin} це звичайний спосіб сказати, що ви кудись сходили й повернулися: {Ma käisin poes}, я сходив до магазину.",
    "{Mida sa eile tegid?} is what did you do yesterday. Take it whole for now; the other persons are the next lesson.": "{Mida sa eile tegid?} означає «що ти робив учора?». Поки що запам'ятайте це цілком; інші особи будуть у наступному уроці.",
    "Now": "Зараз",
    "Say you were at home and read a book.": "Скажіть, що ви були вдома й читали книжку.",
    "I was at home and read a book.": "Я був удома й читав книжку.",
