    "Yesterday I went to the shop.": "Учора я сходив до магазину.",
    "Say you ate cake and drank coffee.": "Скажіть, що ви їли торт і пили каву.",
    "I ate cake and drank coffee.": "Я їв торт і пив каву.",
    "Tom, where were you on Saturday?": "Томе, де ти був у суботу?",
    "I was in Tartu. And Mari was there too.": "Я був у Тарту. І Марі теж там була.",
    "What did you do there?": "Що ти там робив?",
