    "in a café": "у кафе",
    "The past has six forms, -in, -id, -s or -i, -ime, -ite, -id. For {ta} some verbs end in -s and some in -i: {käis}, but {oli} and {tegi}.": "Минулий час має шість форм: -in, -id, -s або -i, -ime, -ite, -id. У формі {ta} одні дієслова закінчуються на -s, а інші на -i: {käis}, але {oli} і {tegi}.",
    "{Sa olid} and {nad olid} are the same word, and so are {sa tegid} and {nad tegid}. The person in front tells you which.": "{Sa olid} і {nad olid} це одне й те саме слово, так само {sa tegid} і {nad tegid}. Хто саме, підказує займенник попереду.",
    "Say you were in Tartu.": "Скажіть, що ви були в Тарту.",
    "Where were you on Saturday?": "Де ти був у суботу?",
    "I was in Tartu.": "Я був у Тарту.",
    "Ask a friend what they did on Sunday.": "Запитайте друга, що він робив у неділю.",
    "What did you do on Sunday?": "Що ти робив у неділю?",
    "Say you went to a café.": "Скажіть, що ви ходили в кафе.",
    "We went to a café.": "Ми ходили в кафе.",
    "Tom, I ask and you answer.": "Томе, я питаю, а ти відповідаєш.",
    "All right.": "Добре.",
    "What do you see?": "Що ти бачиш?",
    "I see a book.": "Я бачу книжку.",
    "And what are you writing?": "А що ти пишеш?",
    "I'm writing a book!": "Я пишу книжку!",
    "Really? Very good! And what do you buy at the shop?": "Справді? Дуже добре! А що ти купуєш у магазині?",
