    "Tom, what month is it now?": "Томе, який зараз місяць?",
    "It's October now. Autumn!": "Зараз жовтень. Осінь!",
    "I like autumn. But I don't like winter.": "Мені подобається осінь. Але зима мені не подобається.",
    "I like winter! In winter it snows.": "Мені подобається зима! Взимку йде сніг.",
    "And in summer?": "А влітку?",
